    {
      "type": "number",
      "quote": "50",
      "gist": "Average number of items of business per weekly meeting"
    },
    {
      "type": "entity",
      "quote": "Federal Council Affairs Section",
      "gist": "Section responsible for checking business items"
    },
    {
      "type": "obligation",
      "quote": "checks that the items of business announced by the departments and the Federal Council are complete and correctly submitted, and that they are sent in on time",
      "gist": "Section must verify completeness, correctness, and timeliness of business items"
    },
    {
      "type": "number",
      "quote": "Four days",
      "gist": "Timeframe before meeting to prepare the agenda"
    },
    {
      "type": "action",
      "quote": "draws up the agenda",
      "gist": "Section prepares the meeting agenda"
    },
    {
      "condition": "As soon as a department or the Federal Council submits a request, the section opens the joint reports procedure, in which the request is distributed to all other departments and the Federal Chancellery",
      "gist": "Joint reports procedure is initiated immediately upon request submission"
    }
  ]
}
